    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. In a review by Lennox et al., they indicated that only 21% of studies reported any information on sustainability outcomes [6].",
      "reason": "Identifies and cites previous reviews and explains the need for the current review by highlighting its unique focus."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review focuses on evaluation approaches for sustainability, not on intervention effects, so describing mechanism of action is not applicable."
    },
